import AuthenticationServices
import SwiftUI
struct SignInView: View { @EnvironmentObject private var auth: AuthManager; @State private var inviteCode = ""; var body: some View { VStack(spacing: 20) { Image(systemName: "checklist").font(.system(size: 58)).foregroundStyle(.green); Text("Family Lists").font(.largeTitle.bold()); Text("Your shared household grocery and to-do lists.").multilineTextAlignment(.center).foregroundStyle(.secondary); TextField("Invitation code", text: $inviteCode).textInputAutocapitalization(.never).autocorrectionDisabled().textFieldStyle(.roundedBorder); SignInWithAppleButton(.signIn) { _ in auth.signIn(inviteCode: inviteCode.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? nil : inviteCode) } onCompletion: { _ in }.frame(height: 50).padding(.top); Text("You need an invitation from a family administrator.").font(.footnote).foregroundStyle(.secondary); if let error = auth.errorMessage { Text(error).foregroundStyle(.red).font(.footnote) } }.padding() } }
